CREATE TABLE my_t (a int);
DELIMITER $$
CREATE PROCEDURE p_case(IN x INT) BEGIN
  DECLARE v INT;
  SET v = CASE WHEN x > 0 THEN 1 ELSE 2 END;
  CASE v WHEN 1 THEN INSERT INTO my_t VALUES (10); ELSE INSERT INTO my_t VALUES (20); END CASE;
END$$
DELIMITER ;
